/// <summary>
/// 玩家技能管理器，挂载在 Player GameObject 上。
/// 管理技能槽位、键位绑定、技能获取/升级/拓展。
/// </summary>
public class PlayerSkillManager : MonoBehaviour, ISkillCaster
{
    [Header("技能槽位")]
    [SerializeField] private List<SkillSlot> _slots = new()
    {
        new SkillSlot { keyBinding = KeyCode.Q },
        new SkillSlot { keyBinding = KeyCode.F },
        new SkillSlot { keyBinding = KeyCode.E },
        new SkillSlot { keyBinding = KeyCode.R },
    };

    [Header("技能库")]
    [SerializeField] private SkillLibrary _skillLibrary;

    [Header("初始技能")]
    [Tooltip("游戏开始时自动装备的技能 ID（留空则不装备）")]
    [SerializeField] private string _initialSkillId;

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;
    private PlayerStats _stats;

    public Vector2 GetTargetDirection()
    {
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;
        return (mouseWorldPos - transform.position).normalized;
    }

    public float GetAttackStrength() => _stats != null ? _stats.AttackStrength : 10f;

    public Projectile.OwnerType GetOwnerType() => Projectile.OwnerType.Player;

    // ---------- 委托 ----------
    /// <summary>技能释放事件：参数为 (槽位索引, 技能数据)</summary>
    public event System.Action<int, SkillData> OnSkillCast;
    /// <summary>技能升级事件</summary>
    public event System.Action<int, int> OnSkillUpgraded;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();
        EquipInitialSkill();
    }

    private void EquipInitialSkill()
    {
        if (string.IsNullOrEmpty(_initialSkillId)) return;
        EquipSkill(0, _initialSkillId);
    }

    void Update()
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            SkillSlot slot = _slots[i];
            slot.Skill?.TickCooldown(Time.deltaTime);

            if (slot.isUnlocked && Input.GetKeyDown(slot.keyBinding))
            {
                CastSkill(i);
            }
        }
    }

    // ---------- 释放 ----------
    private void CastSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return;
        SkillSlot slot = _slots[index];
        if (!slot.isUnlocked || slot.IsEmpty) return;

        Vector2 direction = GetTargetDirection();

        if (slot.TryCast(this, direction))
        {
            OnSkillCast?.Invoke(index, slot.Skill.Data);
        }
    }

    // ---------- 获取与装备 ----------
    /// <summary>从技能库获取技能并装备到第一个空槽</summary>
    public bool AcquireSkill(string skillId)
    {
        if (_skillLibrary == null) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        return instance != null && EquipToEmptySlot(instance);
    }

    /// <summary>装备技能到指定槽位</summary>
    public bool EquipSkill(int index, string skillId)
    {
        if (_skillLibrary == null) return false;
        if (index < 0 || index >= _slots.Count || !_slots[index].isUnlocked) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        if (instance == null) return false;

        _slots[index].Equip(instance);
        return true;
    }

    /// <summary>装备到第一个空槽</summary>
    public bool EquipToEmptySlot(SkillInstance skill)
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            if (_slots[i].isUnlocked && _slots[i].IsEmpty)
            {
                _slots[i].Equip(skill);
                return true;
            }
        }
        return false;
    }

    // ---------- 升级 ----------
    /// <summary>升级指定槽位技能</summary>
    public bool UpgradeSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return false;
        SkillSlot slot = _slots[index];
        if (slot.IsEmpty) return false;

        if (slot.Skill.TryUpgrade())
        {
            OnSkillUpgraded?.Invoke(index, slot.Skill.Level);
            return true;
        }
        return false;
    }

    // ---------- 槽位管理 ----------
    /// <summary>拓展技能槽数量</summary>
    public void ExpandSlots(int additionalSlots)
    {
        for (int i = 0; i < additionalSlots; i++)
        {
            _slots.Add(new SkillSlot { keyBinding = KeyCode.None, isUnlocked = true });
        }
    }

    /// <summary>解锁指定槽位</summary>
    public void UnlockSlot(int index)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].isUnlocked = true;
    }

    // ---------- 键位 ----------
    /// <summary>重新绑定槽位键位</summary>
    public void RebindKey(int index, KeyCode newKey)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].keyBinding = newKey;
    }

    /// <summary>获取槽位技能（供外部查询，如UI）</summary>
    public SkillInstance GetSkill(int index)
    {
        return (index >= 0 && index < _slots.Count) ? _slots[index].Skill : null;
    }

    /// <summary>查询槽位是否解锁（供 UI Controller 读取）</summary>
    public bool IsSlotUnlocked(int index)
    {
        return index >= 0 && index < _slots.Count && _slots[index].isUnlocked;
    }

    /// <summary>获取槽位绑定的快捷键（供 UI Controller 读取）</summary>
    public KeyCode GetKeyCode(int index)
    {
        if (index < 0 || index >= _slots.Count) return KeyCode.None;
        return _slots[index].keyBinding;
    }

    public int SlotCount => _slots.Count;
}

using System.Collections.Generic;
using System.Linq;
using UnityEngine;

/// <summary>
/// 技能库（ScriptableObject）—— 所有技能的唯一工厂入口。
/// 右键 -> Create -> Game -> Skill Library 创建。
/// </summary>
[CreateAssetMenu(fileName = "SkillLibrary", menuName = "Game/Skill Library")]
public class SkillLibrary : ScriptableObject
{
    [SerializeField] private List<SkillData> _allSkills;

    /// <summary>所有技能列表</summary>
    public IReadOnlyList<SkillData> AllSkills => _allSkills;

    /// <summary>通过 ID 查找技能数据</summary>
    public SkillData GetById(string skillId)
    {
        return _allSkills?.Find(s => s.skillId == skillId);
    }

    /// <summary>
    /// 创建完整可用的技能实例（SkillLibrary 是唯一工厂入口）。
    /// 自动注入 OnExecute 委托，优先使用 skillEffect 策略，其次 projectilePrefab。
    /// </summary>
    public SkillInstance CreateSkillInstance(string skillId)
    {
        SkillData data = GetById(skillId);
        if (data == null)
        {
            Debug.LogWarning($"SkillLibrary: 未找到 skillId='{skillId}'");
            return null;
        }

        SkillInstance instance = new SkillInstance(data);

        // 注入 OnExecute 委托
        instance.OnExecute += (caster, direction) =>
        {
            Projectile.OwnerType ownerType = caster.GetOwnerType();

            if (data.skillEffect != null)
            {
                data.skillEffect.Execute(caster, direction,
                    instance.CurrentDamageMultiplier, ownerType);
            }
            else if (data.projectilePrefab != null)
            {
                // 旧方式兼容：直接生成投射物
                GameObject go = Instantiate(data.projectilePrefab,
                    caster.CasterTransform.position, Quaternion.identity);
                Projectile proj = go.GetComponent<Projectile>();
                if (proj == null) proj = go.AddComponent<Projectile>();
                proj.Initialize(direction, data.castRange,
                    caster.GetAttackStrength() * instance.CurrentDamageMultiplier,
                    ownerType);
            }
        };

        return instance;
    }

    /// <summary>随机获取一个技能数据</summary>
    public SkillData GetRandom()
    {
        if (_allSkills == null || _allSkills.Count == 0) return null;
        return _allSkills[Random.Range(0, _allSkills.Count)];
    }

    /// <summary>
    /// 随机创建一个技能实例
    /// </summary>
    public SkillInstance CreateRandomInstance()
    {
        SkillData data = GetRandom();
        return data != null ? new SkillInstance(data) : null;
    }

    /// <summary>随机获取 N 个不重复的技能数据</summary>
    public List<SkillData> GetRandomDistinct(int count)
    {
        if (_allSkills == null || _allSkills.Count == 0) return new List<SkillData>();

        var shuffled = _allSkills.OrderBy(_ => Random.value).ToList();
        int take = Mathf.Min(count, shuffled.Count);
        return shuffled.GetRange(0, take);
    }
}

using System;
using UnityEngine;

/// <summary>
/// 技能运行时实例，持有 SkillData + 等级 + 冷却状态。
/// 通过 OnExecute 委托注入具体释放效果。
/// </summary>
public class SkillInstance
{
    public SkillData Data { get; private set; }
    public int Level { get; private set; } = 1;
    public int MaxLevel => Data.maxLevel;
    public bool IsMaxLevel => Level >= MaxLevel;
    public bool IsCoolingDown { get; private set; }

    private float _cooldownRemaining;

    /// <summary>剩余冷却秒数（供 UI 读取）</summary>
    public float CooldownRemaining => _cooldownRemaining;

    /// <summary>冷却进度 0~1，1=满冷却（刚释放），0=冷却完毕（供 UI 读取）</summary>
    public float CooldownPercent
    {
        get
        {
            float total = CurrentCooldown;
            return total > 0f ? Mathf.Clamp01(_cooldownRemaining / total) : 0f;
        }
    }

    /// <summary>当前等级冷却时间（每级减少10%）</summary>
    public float CurrentCooldown => Data.cooldown * (1f - (Level - 1) * 0.1f);

    /// <summary>当前等级伤害系数</summary>
    public float CurrentDamageMultiplier => Data.damageMultiplier * (1f + (Level - 1) * 0.15f);

    /// <summary>技能执行委托：参数为 (施法者, 目标方向)</summary>
    public event Action<ISkillCaster, Vector2> OnExecute;

    public SkillInstance(SkillData data)
    {
        Data = data;
        Level = 1;
    }

    /// <summary>每帧驱动冷却</summary>
    public void TickCooldown(float deltaTime)
    {
        if (!IsCoolingDown) return;
        _cooldownRemaining -= deltaTime;
        if (_cooldownRemaining <= 0f)
        {
            IsCoolingDown = false;
            _cooldownRemaining = 0f;
        }
    }

    /// <summary>尝试释放技能，返回是否成功</summary>
    public bool TryCast(ISkillCaster caster, Vector2 targetDirection)
    {
        if (IsCoolingDown) return false;

        IsCoolingDown = true;
        _cooldownRemaining = CurrentCooldown;

        OnExecute?.Invoke(caster, targetDirection);
        return true;
    }

    /// <summary>升级技能，返回是否成功</summary>
    public bool TryUpgrade()
    {
        if (IsMaxLevel) return false;
        Level++;
        return true;
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// 小地图 UI — 在界面右上角显示房间和走廊的关系图。
/// 从 MapManager.RoomGraph 读取数据，绘制到 RawImage 的 Texture2D 上。
/// </summary>
[RequireComponent(typeof(RawImage))]
public class MinimapUI : MonoBehaviour
{
    [Header("小地图尺寸")]
    [SerializeField] private int _textureSize = 256;
    [SerializeField] private float _uiWidth = 200f;
    [SerializeField] private float _uiHeight = 200f;

    [Header("绘制参数")]
    [SerializeField] private int _corridorWidth = 4;
    [SerializeField] [Range(0.2f, 1f)] private float _roomDisplayScale = 0.55f;

    [Header("房间颜色")]
    [SerializeField] private Color _startColor = new(0.3f, 0.8f, 0.3f);
    [SerializeField] private Color _normalColor = new(0.5f, 0.5f, 0.5f);
    [SerializeField] private Color _treasureColor = new(1f, 0.84f, 0f);
    [SerializeField] private Color _bossColor = new(0.8f, 0.2f, 0.2f);
    [SerializeField] private Color _shopColor = new(0.3f, 0.6f, 1f);
    [SerializeField] private Color _exitColor = new(0.6f, 0.2f, 0.8f);
    [SerializeField] private Color _hiddenColor = new(0.85f, 0.5f, 0.1f);
    [SerializeField] private Color _explorableColor = new(0.25f, 0.25f, 0.25f, 0.45f);
    [SerializeField] private Color _explorableBorderColor = new(0.18f, 0.18f, 0.18f, 0.55f);
    [SerializeField] private Color _explorableCorridorColor = new(0.18f, 0.18f, 0.18f, 0.35f);
    [SerializeField] private Color _currentBorderColor = Color.white;
    [SerializeField] private Color _corridorColor = new(0.28f, 0.28f, 0.28f, 0.7f);
    [SerializeField] private Color _bgColor = new(0f, 0f, 0f, 0.6f);

    private RawImage _rawImage;
    private Texture2D _texture;
    private int _currentRoomId = -1;
    private System.Collections.Generic.HashSet<int> _visitedRoomIds = new();

    private void Awake()
    {
        _rawImage = GetComponent<RawImage>();
        if (_rawImage == null)
            _rawImage = gameObject.AddComponent<RawImage>();

        ResizeUI();
        CreateTexture();
    }

    private void Start()
    {
        // 订阅房间切换事件
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchCompleted += OnRoomSwitchCompleted;

        // 尝试立即绘制；如果地图还没生成，延迟一帧再试
        TryDraw();

        if (_currentRoomId < 0)
            StartCoroutine(DelayedDraw());
    }

    private IEnumerator DelayedDraw()
    {
        yield return null;
        TryDraw();
    }

    private void OnDestroy()
    {
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchCompleted -= OnRoomSwitchCompleted;

        if (_texture != null)
            Destroy(_texture);
    }

    private void OnRoomSwitchCompleted(int newRoomId)
    {
        _visitedRoomIds.Add(newRoomId);
        _currentRoomId = newRoomId;
        var graph = MapManager.Instance?.RoomGraph;
        if (graph != null)
            DrawMap(graph);
    }

    // ==================== 公开方法 ====================

    [ContextMenu("Refresh")]
    public void Refresh()
    {
        var mgr = MapManager.Instance;
        if (mgr == null) return;
        var graph = mgr.RoomGraph;
        if (graph == null) return;
        _currentRoomId = mgr.CurrentRoomId;
        _visitedRoomIds.Add(_currentRoomId);
        DrawMap(graph);
    }

    // ==================== 内部绘制 ====================

    private void ResizeUI()
    {
        var rt = GetComponent<RectTransform>();
        if (rt == null) rt = gameObject.AddComponent<RectTransform>();
        rt.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _uiWidth);
        rt.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, _uiHeight);
    }

    private void CreateTexture()
    {
        _texture = new Texture2D(_textureSize, _textureSize, TextureFormat.RGBA32, false);
        _texture.filterMode = FilterMode.Point;
        _texture.wrapMode = TextureWrapMode.Clamp;
        _rawImage.texture = _texture;
    }

    private void TryDraw()
    {
        var mgr = MapManager.Instance;
        if (mgr == null) return;
        var graph = mgr.RoomGraph;
        if (graph == null || graph.nodes.Count == 0) return;

        _currentRoomId = mgr.CurrentRoomId;
        _visitedRoomIds.Add(_currentRoomId);
        DrawMap(graph);
    }

    private void DrawMap(RoomGraph graph)
    {
        if (_texture == null) CreateTexture();
        if (graph == null || graph.nodes.Count == 0) return;

        // 1. 计算世界边界
        float minX = float.MaxValue, maxX = float.MinValue;
        float minY = float.MaxValue, maxY = float.MinValue;

        foreach (var node in graph.nodes)
        {
            Vector2 half = node.config.roomSize * 0.5f;
            minX = Mathf.Min(minX, node.worldPosition.x - half.x);
            maxX = Mathf.Max(maxX, node.worldPosition.x + half.x);
            minY = Mathf.Min(minY, node.worldPosition.y - half.y);
            maxY = Mathf.Max(maxY, node.worldPosition.y + half.y);
        }

        float worldW = maxX - minX;
        float worldH = maxY - minY;
        if (worldW < 0.001f || worldH < 0.001f) return;

        // 2. 计算缩放比例 (保持宽高比，并预留边距)
        float texPadding = _textureSize * 0.06f;
        float usableSize = _textureSize - texPadding * 2f;
        float scale = Mathf.Min(usableSize / worldW, usableSize / worldH);
        float offsetX = (usableSize - worldW * scale) / 2f;
        float offsetY = (usableSize - worldH * scale) / 2f;

        // 世界坐标 -> 像素坐标
        int WorldToPixelX(float wx) => Mathf.RoundToInt(texPadding + offsetX + (wx - minX) * scale);
        int WorldToPixelY(float wy) => Mathf.RoundToInt(texPadding + offsetY + (wy - minY) * scale);

        // 3. 清空纹理
        Color[] pixels = new Color[_textureSize * _textureSize];
        for (int i = 0; i < pixels.Length; i++)
            pixels[i] = _bgColor;

        // 4. 计算"可探索"房间: 未访问但与已探索房间相邻的房间 (隐藏房除外)
        var explorableIds = new System.Collections.Generic.HashSet<int>();
        foreach (var node in graph.nodes)
        {
            if (_visitedRoomIds.Contains(node.roomId)) continue;
            if (node.roomType == RoomType.Hidden) continue;
            foreach (var conn in node.connections)
            {
                if (_visitedRoomIds.Contains(conn.Key))
                {
                    explorableIds.Add(node.roomId);
                    break;
                }
            }
        }

        // 5. 画走廊 (隐藏房不参与可探索连线)
        foreach (var node in graph.nodes)
        {
            foreach (var conn in node.connections)
            {
                if (node.roomId >= conn.Key) continue;
                var neighbor = graph.GetNode(conn.Key);
                if (neighbor == null) continue;

                // 隐藏房不显示在可探索状态
                if (!_visitedRoomIds.Contains(node.roomId) && node.roomType == RoomType.Hidden) continue;
                if (!_visitedRoomIds.Contains(neighbor.roomId) && neighbor.roomType == RoomType.Hidden) continue;

                bool aVisited = _visitedRoomIds.Contains(node.roomId);
                bool bVisited = _visitedRoomIds.Contains(neighbor.roomId);
                bool aExplorable = explorableIds.Contains(node.roomId);
                bool bExplorable = explorableIds.Contains(neighbor.roomId);

                bool draw = (aVisited || bVisited) && (aVisited || bVisited || aExplorable || bExplorable);
                if (!draw) continue;

                Color lineColor = (aVisited && bVisited) ? _corridorColor : _explorableCorridorColor;

                Vector2 centerA = node.worldPosition;
                Vector2 centerB = neighbor.worldPosition;
                DrawThickLine(pixels,
                    WorldToPixelX(centerA.x), WorldToPixelY(centerA.y),
                    WorldToPixelX(centerB.x), WorldToPixelY(centerB.y),
                    lineColor, _corridorWidth);
            }
        }

        // 6. 画可探索房间: Boss/Exit 用真实颜色，其余用灰色
        foreach (var node in graph.nodes)
        {
            if (!explorableIds.Contains(node.roomId)) continue;

            bool isBossOrExit = node.roomType == RoomType.Boss || node.roomType == RoomType.Exit;
            Color fillColor = isBossOrExit ? GetRoomColor(node.roomType) : _explorableColor;
            Color borderColor = isBossOrExit
                ? Color.Lerp(GetRoomColor(node.roomType), Color.black, 0.3f)
                : _explorableBorderColor;

            Vector2 half = node.config.roomSize * 0.5f * _roomDisplayScale;
            int px1 = ClampPixel(WorldToPixelX(node.worldPosition.x - half.x));
            int py1 = ClampPixel(WorldToPixelY(node.worldPosition.y - half.y));
            int px2 = ClampPixel(WorldToPixelX(node.worldPosition.x + half.x));
            int py2 = ClampPixel(WorldToPixelY(node.worldPosition.y + half.y));

            for (int y = py1; y <= py2; y++)
            {
                for (int x = px1; x <= px2; x++)
                {
                    bool isBorder = (x == px1 || x == px2 || y == py1 || y == py2);
                    pixels[y * _textureSize + x] = isBorder ? borderColor : fillColor;
                }
            }
        }

        // 7. 画已探索房间
        foreach (var node in graph.nodes)
        {
            if (!_visitedRoomIds.Contains(node.roomId)) continue;

            Color roomColor = GetRoomColor(node.roomType);

            Vector2 half = node.config.roomSize * 0.5f * _roomDisplayScale;
            int px1 = ClampPixel(WorldToPixelX(node.worldPosition.x - half.x));
            int py1 = ClampPixel(WorldToPixelY(node.worldPosition.y - half.y));
            int px2 = ClampPixel(WorldToPixelX(node.worldPosition.x + half.x));
            int py2 = ClampPixel(WorldToPixelY(node.worldPosition.y + half.y));

            for (int y = py1; y <= py2; y++)
            {
                for (int x = px1; x <= px2; x++)
                {
                    bool isBorder = (x == px1 || x == px2 || y == py1 || y == py2);

                    if (isBorder)
                    {
                        pixels[y * _textureSize + x] = Color.Lerp(roomColor, Color.black, 0.3f);
                    }
                    else
                    {
                        pixels[y * _textureSize + x] = roomColor;
                    }
                }
            }

            // 8. 高亮当前房间边框
            if (node.roomId == _currentRoomId)
            {
                for (int y = py1; y <= py2; y++)
                {
                    for (int x = px1; x <= px2; x++)
                    {
                        bool isBorder = (x == px1 || x == px2 || y == py1 || y == py2);
                        if (isBorder)
                            pixels[y * _textureSize + x] = _currentBorderColor;
                    }
                }
            }
        }

        _texture.SetPixels(pixels);
        _texture.Apply();
    }

    private int ClampPixel(int val)
    {
        return Mathf.Clamp(val, 0, _textureSize - 1);
    }

    private void DrawThickLine(Color[] pixels, int x0, int y0, int x1, int y1, Color color, int thickness)
    {
        int dx = Mathf.Abs(x1 - x0);
        int dy = Mathf.Abs(y1 - y0);
        int sx = x0 < x1 ? 1 : -1;
        int sy = y0 < y1 ? 1 : -1;
        int err = dx - dy;
        int half = thickness / 2;

        while (true)
        {
            // 画中心点周围的方形
            for (int dy2 = -half; dy2 <= half; dy2++)
            {
                for (int dx2 = -half; dx2 <= half; dx2++)
                {
                    int tx = x0 + dx2;
                    int ty = y0 + dy2;
                    if (tx >= 0 && tx < _textureSize && ty >= 0 && ty < _textureSize)
                        pixels[ty * _textureSize + tx] = color;
                }
            }

            if (x0 == x1 && y0 == y1) break;

            int e2 = 2 * err;
            if (e2 > -dy) { err -= dy; x0 += sx; }
            if (e2 < dx) { err += dx; y0 += sy; }
        }
    }

    private Color GetRoomColor(RoomType type)
    {
        return type switch
        {
            RoomType.Start => _startColor,
            RoomType.Normal => _normalColor,
            RoomType.Treasure => _treasureColor,
            RoomType.Boss => _bossColor,
            RoomType.Shop => _shopColor,
            RoomType.Exit => _exitColor,
            RoomType.Hidden => _hiddenColor,
            _ => Color.gray
        };
    }
}

using UnityEngine;

/// <summary>
/// 技能 UI Controller —— 监听 PlayerSkillManager（Model），通知 SkillUIPanel（View）。
/// 本类是 Model ↔ View 的唯一耦合点。
/// </summary>
public class SkillUIController : MonoBehaviour
{
    [Header("Model 引用")]
    [SerializeField] private PlayerSkillManager _skillManager;

    [Header("View 引用")]
    [SerializeField] private SkillUIPanel _panel;

    private SkillViewData[] _previousData = System.Array.Empty<SkillViewData>();

    // ==================== 生命周期 ====================

    private void Start()
    {
        if (_skillManager == null)
        {
            Debug.LogError("SkillUIController: PlayerSkillManager 未赋值", this);
            return;
        }
        if (_panel == null)
        {
            Debug.LogError("SkillUIController: SkillUIPanel 未赋值", this);
            return;
        }

        _panel.Initialize(_skillManager.SlotCount);
        _previousData = new SkillViewData[_skillManager.SlotCount];

        // 订阅 Model 事件
        _skillManager.OnSkillCast += HandleSkillCast;
        _skillManager.OnSkillUpgraded += HandleSkillUpgraded;

        // 初始全量刷新
        for (int i = 0; i < _skillManager.SlotCount; i++)
            SyncSlot(i);
    }

    private void Update()
    {
        if (_skillManager == null) return;

        // 每帧同步冷却变化（冷却值通过 SkillInstance 的公开属性读取）
        for (int i = 0; i < _skillManager.SlotCount; i++)
            SyncSlot(i);
    }

    private void OnDestroy()
    {
        if (_skillManager != null)
        {
            _skillManager.OnSkillCast -= HandleSkillCast;
            _skillManager.OnSkillUpgraded -= HandleSkillUpgraded;
        }
    }

    // ==================== Model 事件回调 ====================

    private void HandleSkillCast(int index, SkillData data) => SyncSlot(index);
    private void HandleSkillUpgraded(int index, int newLevel) => SyncSlot(index);

    // ==================== 核心同步 ====================

    private void SyncSlot(int index)
    {
        SkillInstance skill = _skillManager.GetSkill(index);
        SkillViewData data = BuildViewData(index, skill);

        if (!data.Equals(_previousData[index]))
        {
            _previousData[index] = data;
            _panel.RefreshSlot(index, data);
        }
    }

    private SkillViewData BuildViewData(int index, SkillInstance skill)
    {
        SkillViewData data = default;

        data.IsUnlocked = _skillManager.IsSlotUnlocked(index);
        data.IsEquipped = skill != null;
        data.ShowKeyLabel = true;

        // 快捷键标签
        KeyCode key = _skillManager.GetKeyCode(index);
        data.KeyLabel = KeyCodeToString(key);

        if (skill != null)
        {
            SkillData def = skill.Data;
            data.Icon = def.icon;
            data.Level = skill.Level;
            data.MaxLevel = skill.MaxLevel;
            data.IsCoolingDown = skill.IsCoolingDown;
            data.CooldownPercent = skill.CooldownPercent;
            data.CooldownRemaining = skill.CooldownRemaining;
        }

        return data;
    }

    private static string KeyCodeToString(KeyCode key)
    {
        // 提取字母/数字部分，去除 "Alpha" 前缀
        string s = key.ToString();
        if (s.StartsWith("Alpha"))
            return s.Substring(5);
        return s;
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 地图生成器 — 基于配置生成房间图和布局
/// 
/// 算法:
/// 1. 从 Start 房间开始 (放置在中心)
/// 2. BFS 扩展: 每次从已放置房间的未占用门出发
/// 3. 随机选取匹配门方向的房间配置
/// 4. 根据门的本地坐标对齐相邻房间
/// 5. Boss/Exit 放最后，隐藏房从非终点的开放门放置
/// </summary>
public class MapGenerator
{
    private MapConfig _config;
    private int _seed;

    public MapGenerator(MapConfig config)
    {
        _config = config;
    }

    /// <summary>生成房间图</summary>
    public RoomGraph Generate(int seed)
    {
        _seed = seed;
        if (_seed != 0)
            Random.InitState(_seed);
        else
            Random.InitState(System.DateTime.Now.Millisecond);

        var graph = new RoomGraph();

        if (_config.startRoom == null)
        {
            Debug.LogError("MapGenerator: startRoom 未配置!");
            return graph;
        }

        // 1. 放置 Start 房间在中心
        var startNode = graph.AddNode(_config.startRoom, RoomType.Start, Vector2.zero);
        graph.startRoomId = startNode.roomId;

        // 2. 构建需要生成的房间类型队列 (打乱顺序)
        var roomTypeQueue = BuildRoomTypeQueue();

        // 3. BFS 放置
        var placedOpenDoors = new List<(int roomId, DoorDirection dir)>();
        AddOpenDoors(placedOpenDoors, startNode);

        var placedRoomIds = new List<int> { startNode.roomId };
        int typeQueueIndex = 0;
        int failsafe = 0;
        const int maxAttempts = 200;

        while (typeQueueIndex < roomTypeQueue.Count && placedOpenDoors.Count > 0 && failsafe < maxAttempts)
        {
            failsafe++;

            // 随机选一个开放的门
            int doorIdx = Random.Range(0, placedOpenDoors.Count);
            var (anchorId, anchorDir) = placedOpenDoors[doorIdx];
            placedOpenDoors.RemoveAt(doorIdx);

            var anchorNode = graph.GetNode(anchorId);
            if (anchorNode == null) continue;

            RoomType targetType = roomTypeQueue[typeQueueIndex];

            // Boss/Exit 不与 Start 房间直连，跳过该门
            if ((targetType == RoomType.Boss || targetType == RoomType.Exit) && anchorNode.roomType == RoomType.Start)
                continue;
            RoomConfig[] pool = _config.GetPoolForType(targetType);

            if (pool == null || pool.Length == 0)
            {
                // 跳过没有配置该类型池的类型
                typeQueueIndex++;
                // 把这个门放回去，留给下一个房间
                placedOpenDoors.Add((anchorId, anchorDir));
                continue;
            }

            // 随机选取匹配门方向的房间
            var targetDir = RoomConfig.OppositeDir(anchorDir);
            var candidates = new List<RoomConfig>();
            foreach (var rc in pool)
            {
                if (rc != null && rc.HasDoor(targetDir))
                    candidates.Add(rc);
            }

            if (candidates.Count == 0)
            {
                // 没有可用的候选，跳过
                continue;
            }

            var chosenConfig = candidates[Random.Range(0, candidates.Count)];

            // 计算新房间位置
            Vector2 anchorDoorWorld = anchorNode.GetDoorWorldPosition(anchorDir);
            Vector2 targetDoorLocal = chosenConfig.GetDoorOffset(targetDir);
            Vector2 newPos = anchorDoorWorld - targetDoorLocal;

            // 碰撞检测
            var newBounds = new Rect(newPos - chosenConfig.roomSize * 0.5f, chosenConfig.roomSize);
            if (OverlapsAny(graph, newBounds))
            {
                // 放回门，稍后重试
                placedOpenDoors.Add((anchorId, anchorDir));
                continue;
            }

            // 成功放置
            var newNode = graph.AddNode(chosenConfig, targetType, newPos);
            graph.Connect(anchorId, newNode.roomId, anchorDir, targetDir);
            placedRoomIds.Add(newNode.roomId);

            // 将新房间的未连接门加入开放列表
            AddOpenDoors(placedOpenDoors, newNode, targetDir);

            // 如果是 Exit 房间，记录
            if (targetType == RoomType.Exit)
                graph.exitRoomId = newNode.roomId;

            // 如果是 Boss 房间，记录 (hasBoss=true 时 Exit 不在队列中)
            // if (targetType == RoomType.Boss) {} // Boss 无需额外处理

            typeQueueIndex++;
        }

        // 如果 Exit 还没放置 (hasBoss=false 且 BFS 主循环未成功放置)，兜底放置
        if (graph.exitRoomId == 0 && !_config.hasBoss && _config.exitRoom != null)
        {
            PlaceExitRoomFarthest(graph, placedOpenDoors);
        }

        // 放置隐藏房：从非 Boss/Exit 房间的开放门中随机选取
        PlaceHiddenRooms(graph, placedOpenDoors);

        if (failsafe >= maxAttempts)
            Debug.LogWarning("MapGenerator: 达到最大尝试次数，可能未生成全部房间");

        Debug.Log($"MapGenerator: 生成了 {graph.nodes.Count} 个房间 (预期 {_config.TotalRooms})");
        return graph;
    }

    /// <summary>构建房间类型队列 (打乱，最终Boss/Exit放最后)</summary>
    private List<RoomType> BuildRoomTypeQueue()
    {
        var queue = new List<RoomType>();

        for (int i = 0; i < _config.normalRoomCount; i++)
            queue.Add(RoomType.Normal);
        for (int i = 0; i < _config.treasureRoomCount; i++)
            queue.Add(RoomType.Treasure);
        for (int i = 0; i < _config.shopRoomCount; i++)
            queue.Add(RoomType.Shop);

        // 最终房间: Boss 或 Exit 二选一，放最后
        if (_config.hasBoss)
        {
            for (int i = 0; i < _config.bossRoomCount; i++)
                queue.Add(RoomType.Boss);
        }
        else
        {
            queue.Add(RoomType.Exit);
        }

        // 打乱除最后一个 (Boss/Exit) 之外的所有房间
        int shuffleCount = queue.Count - 1;
        for (int i = 0; i < shuffleCount; i++)
        {
            int j = Random.Range(i, shuffleCount);
            (queue[i], queue[j]) = (queue[j], queue[i]);
        }

        return queue;
    }

    /// <summary>兜底放置 Exit: 从开放门中选距离 Start 最远的那个</summary>
    private void PlaceExitRoomFarthest(RoomGraph graph, 
        List<(int roomId, DoorDirection dir)> openDoors)
    {
        if (openDoors.Count == 0) return;

        var startNode = graph.GetNode(graph.startRoomId);
        Vector2 startPos = startNode != null ? startNode.worldPosition : Vector2.zero;

        // 找距离 Start 最远的开放门
        var candidates = new List<(int roomId, DoorDirection dir, float dist)>();
        foreach (var od in openDoors)
        {
            var node = graph.GetNode(od.roomId);
            if (node == null) continue;
            // 估算门位置
            Vector2 doorPos = node.GetDoorWorldPosition(od.dir);
            float dist = Vector2.Distance(doorPos, startPos);
            candidates.Add((od.roomId, od.dir, dist));
        }
        candidates.Sort((a, b) => b.dist.CompareTo(a.dist)); // 降序

        foreach (var (roomId, dir, _) in candidates)
        {
            var anchorNode = graph.GetNode(roomId);
            if (anchorNode == null) continue;

            var opp = RoomConfig.OppositeDir(dir);
            if (!_config.exitRoom.HasDoor(opp)) continue;

            Vector2 anchorDoorWorld = anchorNode.GetDoorWorldPosition(dir);
            Vector2 targetDoorLocal = _config.exitRoom.GetDoorOffset(opp);
            Vector2 newPos = anchorDoorWorld - targetDoorLocal;
            var newBounds = new Rect(newPos - _config.exitRoom.roomSize * 0.5f, _config.exitRoom.roomSize);
            if (OverlapsAny(graph, newBounds)) continue;

            var exitNode = graph.AddNode(_config.exitRoom, RoomType.Exit, newPos);
            graph.Connect(roomId, exitNode.roomId, dir, opp);
            graph.exitRoomId = exitNode.roomId;
            Debug.Log("MapGenerator: Exit 放置在距离 Start 最远的开放门");
            return;
        }

        Debug.LogWarning("MapGenerator: 无法为 Exit 找到合适位置");
    }

    /// <summary>将房间的未使用门加入开放列表</summary>
    private void AddOpenDoors(List<(int roomId, DoorDirection dir)> openDoors, RoomNode node, 
        DoorDirection? excludeDir = null)
    {
        var allDirs = new[] { DoorDirection.Top, DoorDirection.Bottom, DoorDirection.Left, DoorDirection.Right };
        foreach (var dir in allDirs)
        {
            if (excludeDir.HasValue && dir == excludeDir.Value) continue;
            if (node.config.HasDoor(dir))
                openDoors.Add((node.roomId, dir));
        }
    }

    /// <summary>放置隐藏房：从非 Boss/Exit 房间的开放门中随机选取放置</summary>
    private void PlaceHiddenRooms(RoomGraph graph, 
        List<(int roomId, DoorDirection dir)> openDoors)
    {
        if (_config.hiddenRoomPool == null || _config.hiddenRoomPool.Length == 0) return;
        int count = _config.hiddenRoomCount;
        if (count <= 0) return;

        // 收集非 Boss/Exit 房间的开放门
        var eligibleDoors = new List<(int roomId, DoorDirection dir)>();
        foreach (var od in openDoors)
        {
            var node = graph.GetNode(od.roomId);
            if (node == null) continue;
            if (node.roomType == RoomType.Boss || node.roomType == RoomType.Exit) continue;
            eligibleDoors.Add(od);
        }

        if (eligibleDoors.Count == 0) return;

        int placed = 0;
        int failsafe = 0;
        const int maxAttempts = 50;

        while (placed < count && eligibleDoors.Count > 0 && failsafe < maxAttempts)
        {
            failsafe++;

            // 随机选一个可用的开放门
            int idx = Random.Range(0, eligibleDoors.Count);
            var (anchorId, anchorDir) = eligibleDoors[idx];
            eligibleDoors.RemoveAt(idx);

            var anchorNode = graph.GetNode(anchorId);
            if (anchorNode == null) continue;

            var targetDir = RoomConfig.OppositeDir(anchorDir);

            // 选取匹配的隐藏房配置
            var candidates = new List<RoomConfig>();
            foreach (var rc in _config.hiddenRoomPool)
            {
                if (rc != null && rc.HasDoor(targetDir))
                    candidates.Add(rc);
            }
            if (candidates.Count == 0) continue;

            var chosenConfig = candidates[Random.Range(0, candidates.Count)];

            Vector2 anchorDoorWorld = anchorNode.GetDoorWorldPosition(anchorDir);
            Vector2 targetDoorLocal = chosenConfig.GetDoorOffset(targetDir);
            Vector2 newPos = anchorDoorWorld - targetDoorLocal;

            var newBounds = new Rect(newPos - chosenConfig.roomSize * 0.5f, chosenConfig.roomSize);
            if (OverlapsAny(graph, newBounds)) continue;

            var newNode = graph.AddNode(chosenConfig, RoomType.Hidden, newPos);
            graph.Connect(anchorId, newNode.roomId, anchorDir, targetDir);
            // 不把隐藏房的门加入开放列表 (保证只有一个连接)
            placed++;
        }

        if (placed < count)
            Debug.LogWarning($"MapGenerator: 只放置了 {placed}/{count} 个隐藏房");
    }

    /// <summary>检查矩形是否与已有房间重叠。
    /// 相邻房间共享边界 (edge-to-edge) 不算重叠，只有真正交叉才冲突。
    /// roomSpacing 用作最小间隔。</summary>
    private bool OverlapsAny(RoomGraph graph, Rect bounds)
    {
        // 缩一圈来确保最小间距 (只对真正相交的生效)
        float shrink = _config.roomSpacing * 0.5f;
        var checkRect = new Rect(
            bounds.x + shrink,
            bounds.y + shrink,
            bounds.width - shrink * 2,
            bounds.height - shrink * 2
        );

        foreach (var node in graph.nodes)
        {
            var otherRect = new Rect(
                node.Bounds.x + shrink,
                node.Bounds.y + shrink,
                node.Bounds.width - shrink * 2,
                node.Bounds.height - shrink * 2
            );

            if (checkRect.Overlaps(otherRect))
                return true;
        }
        return false;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerController : MonoBehaviour
{
    private Rigidbody2D _rb;
    private PlayerCombat _combat;
    private PlayerStats _stats;
    private Vector2 _moveInput;

    /// <summary>攻击输入委托，由 PlayerCombat 订阅</summary>
    public event System.Action OnAttackInput;

    /// <summary>输入是否被锁定 (房间切换期间)</summary>
    public bool InputLocked { get; set; }

    void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        _combat = GetComponent<PlayerCombat>();
        _stats = GetComponent<PlayerStats>();

        if (_combat != null)
            OnAttackInput += _combat.TryShoot;

#if UNITY_EDITOR
        if (_rb == null)
            Debug.LogWarning("PlayerController: 未找到 Rigidbody2D 组件！");
        if (_combat == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerCombat 组件！");
        if (_stats == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerStats 组件！");
#endif
    }

    void Start()
    {
        if (_stats == null) return;

        CircleCollider2D circle = GetComponent<CircleCollider2D>();
        if (circle != null)
        {
            _stats.ColliderRadius = circle.radius * Mathf.Max(transform.localScale.x, transform.localScale.y);
        }

        // Start 时 MapManager.Instance 已经初始化 (Awake 时序保证)
        if (MapManager.Instance != null)
        {
            MapManager.Instance.OnRoomSwitchStarted += (f, t) => InputLocked = true;
            MapManager.Instance.OnRoomSwitchCompleted += (t) => InputLocked = false;
        }
    }

    void Update()
    {
        if (_stats != null && _stats.IsDead) return;
        if (InputLocked)
        {
            _moveInput = Vector2.zero;
            return;
        }

        float horizontal = Input.GetAxisRaw("Horizontal");
        float vertical = Input.GetAxisRaw("Vertical");
        _moveInput = new Vector2(horizontal, vertical);
        _moveInput = Vector2.ClampMagnitude(_moveInput, 1f);

        if (Input.GetMouseButtonDown(0))
        {
            OnAttackInput?.Invoke();
        }
    }

    void FixedUpdate()
    {
        if (_rb == null || _stats == null) return;
        if (_stats.IsDead) return;
        if (InputLocked) return;

        // 使用 Rigidbody2D 物理驱动，墙壁碰撞由 Collider2D 处理
        _rb.velocity = _moveInput * _stats.MoveSpeed;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerCombat : MonoBehaviour
{
    [Header("射击配置")]
    [SerializeField] private GameObject bulletPrefab;

    private PlayerStats _stats;
    private float _lastShootTime = -10f;

    /// <summary>射击事件委托：参数为 (方向, 子弹速度, 攻击力)</summary>
    public event System.Action<Vector2, float, float> OnShoot;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();

        if (bulletPrefab == null)
        {
#if UNITY_EDITOR
            Debug.LogWarning("PlayerCombat: 未指定子弹预制体！");
#endif
        }
    }

    /// <summary>尝试射击，由 PlayerController 通过委托调用</summary>
    public void TryShoot()
    {
        if (bulletPrefab == null || _stats == null)
            return;

        if (Time.time < _lastShootTime + _stats.ShootCooldown)
            return;

        // 获取鼠标世界位置
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;

        Vector2 direction = (mouseWorldPos - transform.position).normalized;

        float bulletSpeed = _stats.BulletSpeed;
        float attackStrength = _stats.AttackStrength;

        // 生成子弹
        GameObject bullet = Instantiate(bulletPrefab, transform.position, Quaternion.identity);
        Projectile proj = bullet.GetComponent<Projectile>();
        if (proj != null)
        {
            proj.Initialize(direction, bulletSpeed, attackStrength, Projectile.OwnerType.Player);
        }
#if UNITY_EDITOR
        else
        {
            Debug.LogWarning("子弹预制体缺少 Projectile 组件！");
        }
#endif

        _lastShootTime = Time.time;

        OnShoot?.Invoke(direction, bulletSpeed, attackStrength);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 玩家所有数值属性的唯一数据源。
/// PlayerController 和 PlayerCombat 通过引用读取所需属性。
/// </summary>
public class PlayerStats : MonoBehaviour, IDamageable, IHealable
{
    [Header("生命属性")]
    [SerializeField] private float maxHealth = 100f;
    [SerializeField] private float health = 100f;

    [Header("移动属性")]
    [SerializeField] private float moveSpeed = 5f;

    [Header("攻击属性")]
    [SerializeField] private float attackStrength = 10f;

    [Header("射击属性")]
    [SerializeField] private float bulletSpeed = 10f;
    [SerializeField] private float shootCooldown = 0.2f;

    [Header("碰撞属性")]
    [SerializeField] private float colliderRadius = 0.4f;

    private bool _isDead = false;

    // ---------- 只读属性 ----------
    public float CurrentHealth => health;
    public float MaxHealth => maxHealth;
    public bool IsDead => _isDead;
    public float MoveSpeed => moveSpeed;
    public float AttackStrength => attackStrength;
    public float BulletSpeed => bulletSpeed;
    public float ShootCooldown => shootCooldown;
    public float ColliderRadius
    {
        get => colliderRadius;
        set => colliderRadius = Mathf.Max(value, 0.01f);
    }

    // ---------- 委托 ----------
    /// <summary>生命变化委托：参数为 (当前生命, 最大生命)</summary>
    public event System.Action<float, float> OnHealthChanged;
    /// <summary>死亡委托</summary>
    public event System.Action OnDied;
    /// <summary>属性变化委托：参数为 (属性名)</summary>
    public event System.Action<string> OnStatChanged;

    private void Awake()
    {
        health = maxHealth;
    }

    // ---------- IDamageable ----------
    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        health -= damage;
        health = Mathf.Max(health, 0);

#if UNITY_EDITOR
        Debug.Log($"玩家受击！剩余生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");

        if (health <= 0f)
        {
            Die();
        }
    }

    // ---------- IHealable ----------
    public void Heal(float amount)
    {
        if (_isDead) return;

        health = Mathf.Min(health + amount, maxHealth);

#if UNITY_EDITOR
        Debug.Log($"玩家治疗！当前生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");
    }

    private void Die()
    {
        _isDead = true;
        Debug.Log("玩家死亡");

        OnDied?.Invoke();
    }

    // ---------- 数值修正 ----------
    private void OnValidate()
    {
        health = Mathf.Clamp(health, 0, maxHealth);
        maxHealth = Mathf.Max(maxHealth, 1f);
        moveSpeed = Mathf.Max(moveSpeed, 0);
        attackStrength = Mathf.Max(attackStrength, 0);
        bulletSpeed = Mathf.Max(bulletSpeed, 0f);
        shootCooldown = Mathf.Max(shootCooldown, 0f);
        colliderRadius = Mathf.Max(colliderRadius, 0.01f);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

